// Typed access to the committed snapshot in data/ (see data/README.md).
// The JSON is generated by scripts/data/build-snapshot.mjs, which checks that
// every row's source_id, county_id and indicator_id resolve before writing.

import countiesJson from "@/data/counties.json";
import dataGapsJson from "@/data/data-gaps.json";
import evidenceJson from "@/data/evidence.json";
import gapsJson from "@/data/gaps.json";
import indicatorsJson from "@/data/indicators.json";
import roadmapJson from "@/data/roadmap.json";
import sourcesJson from "@/data/sources.json";
import valuesJson from "@/data/values.json";

export type SourceId = string;

export type Source = {
  source_id: SourceId;
  kind: "statistic" | "evidence";
  name: string;
  url: string;
  publisher: string;
  retrieved: string; // ISO date we took the snapshot
  data_updated: string | null; // ISO date the publisher last updated the data
};

export type AreaKind = "county" | "city" | "country";

export type County = {
  id: string; // URL slug, e.g. "vantaa-kerava"
  kind: AreaKind;
  name: string;
  name_fi: string;
  sotkanet_region_id: number;
  source_id: SourceId;
};

export type Stage = "gp_access" | "gp_recognition" | "referral";

export type Indicator = {
  indicator_id: string; // Sotkanet id, e.g. "6411"
  name: string;
  short_name: string;
  unit: string;
  direction: "higher_is_worse" | "lower_is_worse";
  stage: Stage | null; // null: context only, not used for stage status
  limitation: string;
  source_id: SourceId;
};

export type IndicatorValue = {
  county_id: string;
  indicator_id: string;
  year: number;
  value: number;
  abs_value: number | null;
  source_id: SourceId;
};

export type GapStatus = "red" | "amber" | "no_data";

export type Gap = {
  county_id: string;
  stage: Stage;
  indicator_id: string;
  year: number;
  status: GapStatus;
  /** The area's own value. Null when Sotkanet has none (status no_data). */
  value: number | null;
  /**
   * Set when the area has no value of its own but a wider one exists: the HUS
   * hospital group handles referrals for four Uusimaa counties. Show it
   * labelled as shared, never as the county's figure. It does not set status.
   */
  shared?: {
    name: string;
    value: number;
    trend: { year: number; value: number }[];
    confirmed_by: SourceId;
  };
  national_value: number;
  note: string;
  source_id: SourceId;
};

export type Evidence = {
  id: string;
  stage: Stage;
  action: string;
  detail: string;
  who_implements: string;
  first_step: string;
  precedent: string;
  effect_text: string;
  /** `population`: who/where/against what the figure was measured, only where the stored text says so. */
  effect_size: { value: number; unit: string; metric: string; population?: string } | null;
  quote_or_page: string;
  limitations: string;
  verified: boolean;
  source_id: SourceId;
};

/**
 * A measure of the national cancer strategy's implementation roadmap 2026-2031, as the roadmap
 * states it (our English; `pages` is the printed page of the Finnish original). Euro figures in
 * `funding` are national funding needs, never a county's cost.
 */
export type RoadmapMeasure = {
  measure_id: string; // "2.5.1"
  goal: number; // the strategy's main goal, 1 to 4
  goal_title: string;
  title: string;
  responsible: string;
  funding: string;
  schedule: { period: string; text: string }[];
  indicator: string | null;
  pages: string;
  /** Actions (evidence ids) whose own text names this measure or the model it builds on. */
  evidence_ids: string[];
  source_id: SourceId;
};

/** Where on the way to treatment a missing figure sits: the three steps, then the hospital's. */
export type GapStep = Stage | "diagnosis" | "treatment";

/** A figure nobody publishes yet, as a to-do: who could publish it and what a county can do now. */
export type DataGap = {
  id: string;
  step: GapStep;
  missing: string;
  today: string;
  /** Our proposal, shown labelled as one. */
  could_publish: string;
  measure_id: string | null;
  county_can: string;
  /** Null: every area. Otherwise only the named areas. */
  applies_to: string[] | null;
  source_id: SourceId;
};

// JSON imports are typed structurally (e.g. kind: string); the build script
// guarantees the narrower types, so the casts here are safe.
export const sources = sourcesJson as Source[];
export const areas = countiesJson as County[];
export const indicators = indicatorsJson as Indicator[];
export const values = valuesJson as IndicatorValue[];
export const gaps = gapsJson as Gap[];
export const evidence = evidenceJson as Evidence[];
export const roadmap = roadmapJson as RoadmapMeasure[];
export const dataGaps = dataGapsJson as DataGap[];

/** The roadmap measure an action belongs to, if the roadmap names it or its model. */
export function getMeasureForAction(evidenceId: string): RoadmapMeasure | undefined {
  return roadmap.find((measure) => measure.evidence_ids.includes(evidenceId));
}

export function getMeasure(measureId: string): RoadmapMeasure | undefined {
  return roadmap.find((measure) => measure.measure_id === measureId);
}

/** The data gaps that apply to an area (all the national ones, plus any named for it). */
export function getDataGaps(countyId?: string): DataGap[] {
  return dataGaps.filter(
    (gap) => gap.applies_to === null || (countyId !== undefined && gap.applies_to.includes(countyId)),
  );
}

export const LATEST_YEAR = 2025;
export const STAGES: Stage[] = ["gp_access", "gp_recognition", "referral"];

/** The 21 wellbeing services counties plus Helsinki (no national row). */
export const counties = areas.filter((area) => area.kind !== "country");

export function getCounty(id: string): County | undefined {
  return counties.find((county) => county.id === id);
}

export function getSource(sourceId: SourceId): Source | undefined {
  return sources.find((source) => source.source_id === sourceId);
}

export function getValue(
  countyId: string,
  indicatorId: string,
  year: number = LATEST_YEAR,
): IndicatorValue | undefined {
  return values.find(
    (v) => v.county_id === countyId && v.indicator_id === indicatorId && v.year === year,
  );
}

/** Stage status for a county. A stage with no row (gp_recognition) is no public data. */
export function getGaps(countyId: string): Gap[] {
  return gaps.filter((gap) => gap.county_id === countyId);
}

export function getEvidence(stage: Stage): Evidence[] {
  return evidence.filter((row) => row.stage === stage);
}
